// Prompt assembly. Pure functions so the UI can show exactly what gets sent.
//
// Consistency strategy (the core trick behind AI dramas):
//   1. every character gets one reference image, generated once;
//   2. each shot's keyframe is generated by an image-edit model that receives those
//      reference images, so faces and outfits carry over between shots;
//   3. the video model animates that keyframe (image-to-video) instead of inventing
//      the scene from text, so identity survives into motion.

import type { Character, Project, Shot } from "./types";

const clean = (s: string) => s.trim().replace(/\s+/g, " ").replace(/[.\s]+$/, "");

const frameWords: Record<Project["aspectRatio"], string> = {
  "9:16": "vertical 9:16 frame",
  "16:9": "widescreen 16:9 frame",
  "1:1": "square 1:1 frame",
};

export function characterPrompt(project: Project, c: Character) {
  return [
    project.style && `${clean(project.style)}.`,
    `Character reference image for a short drama: ${clean(c.name)}, ${clean(c.description)}.`,
    "Full body from head to toe, front view, standing naturally, neutral expression,",
    "plain light-gray studio background, soft even lighting, sharp focus on the face.",
    "Single person only, no text, no watermark.",
  ]
    .filter(Boolean)
    .join(" ");
}

/** Characters in the shot that already have a reference image, in prompt order (max 10). */
export function shotRefCharacters(project: Project, shot: Shot) {
  return shot.characters
    .map((id) => project.characters.find((c) => c.id === id))
    .filter((c): c is Character => !!c && !!c.image)
    .slice(0, 10);
}

export function keyframePrompt(project: Project, shot: Shot) {
  const refs = shotRefCharacters(project, shot);
  const cast = shot.characters
    .map((id) => project.characters.find((c) => c.id === id))
    .filter((c): c is Character => !!c);
  const lines = [
    project.style && `${clean(project.style)}.`,
    `${clean(shot.shotType || "Medium")} shot, ${frameWords[project.aspectRatio]}.`,
    shot.location && `Setting: ${clean(shot.location)}.`,
    `${clean(shot.imagePrompt || shot.action)}.`,
  ];
  if (cast.length) {
    lines.push(`Characters: ${cast.map((c) => `${clean(c.name)} (${clean(c.description)})`).join("; ")}.`);
  }
  if (refs.length) {
    lines.push(
      `Reference images: ${refs.map((c, i) => `image ${i + 1} is ${clean(c.name)}`).join(", ")}.`,
      "Keep each character's face, hairstyle, body type and outfit exactly as in their reference image.",
    );
  }
  lines.push("Cinematic film still, no text, no subtitles, no watermark.");
  return lines.filter(Boolean).join(" ");
}

export function videoPrompt(project: Project, shot: Shot, withDialogueAudio: boolean) {
  const lines = [`${clean(shot.motionPrompt || shot.action)}.`];
  if (shot.camera) lines.push(`Camera: ${clean(shot.camera)}.`);
  if (shot.dialogue.length) {
    if (withDialogueAudio) {
      for (const d of shot.dialogue) lines.push(`${clean(d.speaker)} says: "${d.line.trim()}"`);
    } else {
      lines.push("The character is speaking; natural mouth movement.");
    }
  }
  if (project.style) lines.push(`Style: ${clean(project.style)}.`);
  lines.push("Keep the characters consistent with the first frame. No subtitles, no captions, no on-screen text.");
  return lines.join(" ");
}
